import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const cursePhysicalScenarios=['curse-ordinary','curse-dedicated'] as const;
export type CursePhysicalScenario=typeof cursePhysicalScenarios[number];
export function isCursePhysicalScenario(name:string):name is CursePhysicalScenario{return (cursePhysicalScenarios as readonly string[]).includes(name);}
export function makeCursePhysicalScenario(name:CursePhysicalScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;follower?:'none'|'metal'|'guardian'}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'邪祭ウーノス');assignCharacter(s,b,'侍大将のシン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[a]!.permanent!.magic_level=20+(options.level??7)-gameStats(s,a).magic_level;s.players[a]!.permanent!.spirit=20+6-gameStats(s,a).spirit;s.players[b]!.permanent!.spirit=20+6-gameStats(s,b).spirit;
 const card=takeCard(s,a,'a2-p13-r3c2'),maai=takeCard(s,b,'a2-p07-r1c1'),evade=takeCard(s,b,'a2-p05-r3c1'),teleport=takeCard(s,b,'a2-p06-r1c1'),fate=takeCard(s,c,'命運凶変'),guard=options.follower==='none'?null:takeCard(s,b,options.follower==='guardian'?'守護者':'メタルゴーレム'),other=options.follower==='none'?null:takeCard(s,c,'兵士'),prayer=options.follower==='guardian'?takeCard(s,a,'必勝の祈り'):null;for(const id of [a,b,c,d])trimHand(s,id,card,maai,evade,teleport,fate,...(guard?[guard]:[]),...(other?[other]:[]),...(prayer?[prayer]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`CURSE_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('CURSE_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('CURSE_IDS');}
 for(const id of [a,b,c,d]){if(guard&&id===b)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});if(other&&id===c)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:other});act(id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return s;
}
